package main
import("bytes";"crypto/sha256";"crypto/tls";"crypto/x509";"encoding/hex";"encoding/json";"flag";"fmt";"io";"net/http";"os";"path/filepath";"time")
type Cursor struct{Offset int64 `json:"offset"`}
type Request struct{Device string `json:"device"`;Offset int64 `json:"offset"`;Data []byte `json:"data"`;SHA256 string `json:"sha256"`}
func main(){url:=flag.String("url","","collector URL");device:=flag.String("device","NC-I-A","certificate-bound device");log:=flag.String("log","/var/log/auth.log","actual audit source");cursor:=flag.String("cursor","/var/db/tdn-audit-exporter/cursor.json","durable acknowledged offset");ca:=flag.String("ca","","CA file");cert:=flag.String("cert","","client certificate");key:=flag.String("key","","client private key");flag.Parse();if err:=run(*url,*device,*log,*cursor,*ca,*cert,*key);err!=nil{fmt.Fprintln(os.Stderr,err);os.Exit(1)}}
func run(url,device,log,cursor,ca,cert,key string)error{c:=Cursor{};if b,e:=os.ReadFile(cursor);e==nil{if e=json.Unmarshal(b,&c);e!=nil{return e}}else if !os.IsNotExist(e){return e};f,e:=os.Open(log);if e!=nil{return e};defer f.Close();st,e:=f.Stat();if e!=nil{return e};if st.Size()<c.Offset{return fmt.Errorf("source shrank below acknowledged offset; explicit rotation handling required")};if _,e=f.Seek(c.Offset,0);e!=nil{return e};data,e:=io.ReadAll(io.LimitReader(f,65536));if e!=nil{return e};if len(data)==0{fmt.Println("no new audit bytes");return nil};sum:=sha256.Sum256(data);digest:=hex.EncodeToString(sum[:]);b,e:=json.Marshal(Request{device,c.Offset,data,digest});if e!=nil{return e};roots:=x509.NewCertPool();pem,e:=os.ReadFile(ca);if e!=nil{return e};if !roots.AppendCertsFromPEM(pem){return fmt.Errorf("CA parse failed")};pair,e:=tls.LoadX509KeyPair(cert,key);if e!=nil{return e};transport:=&http.Transport{TLSClientConfig:&tls.Config{MinVersion:tls.VersionTLS13,MaxVersion:tls.VersionTLS13,RootCAs:roots,Certificates:[]tls.Certificate{pair}}};client:=&http.Client{Transport:transport,Timeout:8*time.Second};resp,e:=client.Post(url,"application/json",bytes.NewReader(b));if e!=nil{return e};defer resp.Body.Close();answer,e:=io.ReadAll(io.LimitReader(resp.Body,4096));if e!=nil{return e};if resp.StatusCode!=200{return fmt.Errorf("collector status %d: %s",resp.StatusCode,answer)};var ack struct{Next int64 `json:"next"`;SHA256 string `json:"sha256"`;Duplicate bool `json:"duplicate"`};if e=json.Unmarshal(answer,&ack);e!=nil{return e};if ack.Next!=c.Offset+int64(len(data))||ack.SHA256!=digest{return fmt.Errorf("collector acknowledgement mismatch")};if e=os.MkdirAll(filepath.Dir(cursor),0700);e!=nil{return e};tmp:=cursor+".tmp";out,e:=os.OpenFile(tmp,os.O_CREATE|os.O_TRUNC|os.O_WRONLY,0600);if e!=nil{return e};encoded,_:=json.Marshal(Cursor{ack.Next});if _,e=out.Write(encoded);e!=nil{return e};if e=out.Sync();e!=nil{return e};if e=out.Close();e!=nil{return e};if e=os.Rename(tmp,cursor);e!=nil{return e};directory,e:=os.Open(filepath.Dir(cursor));if e!=nil{return e};defer directory.Close();if e=directory.Sync();e!=nil{return e};fmt.Printf("acknowledged offset=%d next=%d bytes=%d sha256=%s duplicate=%t TLS=1.3\n",c.Offset,ack.Next,len(data),digest,ack.Duplicate);return nil}
